import numpy as np
L=open('opt.xyz').read().split('\n')[2:]
at=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in L if l.strip()]
rh=at[1][1]
for i,(s,p) in enumerate(at):
    d=np.linalg.norm(p-rh)
    if d<2.7 and i!=1: print(i,s,round(d,3))
# angles
def ang(a,b,c):
    v1=at[a][1]-at[b][1]; v2=at[c][1]-at[b][1]
    return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
for pair in [(17,26),(2,0),(2,18),(0,18),(17,18),(17,2),(0,26),(2,26)]:
    print(pair, round(ang(pair[0],1,pair[1]),1))
